#include <iostream>

int main() {
    // Simulation of CheckPoint 2.20 with fixed epoch timestamp
    long long totalSeconds = 1203183086LL;
    int currentSecond = totalSeconds % 60;
    long long totalMinutes = totalSeconds / 60;
    int currentMinute = totalMinutes % 60;
    long long totalHours = totalMinutes / 60;
    int currentHour = totalHours % 24;

    std::cout << currentHour << ":" << currentMinute << ":" << currentSecond << std::endl;

    // CheckPoint 2.21 trace
    int a = 6;
    a -= a + 1; // a = 6 - (6 + 1) = -1
    std::cout << a << std::endl;
    a *= 6;     // a = -1 * 6 = -6
    std::cout << a << std::endl;
    a /= 2;     // a = -6 / 2 = -3
    std::cout << a << std::endl;

    return 0;
}

#include <iostream>

int main() {
    // CheckPoint 2.23 trace
    int a = 6;
    int b = a++;
    std::cout << a << " " << b << std::endl; // 7 6
    a = 6;
    b = ++a;
    std::cout << a << " " << b << std::endl; // 7 7

    // CheckPoint 2.24 trace
    a = 6;
    b = a--;
    std::cout << a << " " << b << std::endl; // 5 6
    a = 6;
    b = --a;
    std::cout << a << " " << b << std::endl; // 5 5

    // Mixed-type expression and static_cast
    double x = 1.1;
    double y = 5.4;
    double z = x-- + (++y); // 1.1 + 6.4 = 7.5; x becomes 0.1, y becomes 6.4
    std::cout << x << " " << y << " " << z << std::endl;

    int truncated = static_cast<int>(z);
    std::cout << truncated << std::endl;

    return 0;
}
